],[-43.954005,-22.914929],[-43.949286,-22.913189],[-43.947001,-22.916309],[-43.946818,-22.918553]]],[[[-43.901787,-22.912602],[-43.900615,-22.910769],[-43.898116,-22.91073],[-43.895034,-22.90294],[-43.89316,-22.900941],[-43.891803,-22.904714],[-43.883164,-22.900424],[-43.882625,-22.903704],[-43.887075,-22.904733],[-43.889319,-22.905875],[-43.893602,-22.910006],[-43.896959,-22.912228],[-43.90116,-22.913206],[-43.904582,-22.917191],[-43.905728,-22.917222],[-43.908318,-22.91649],[-43.904876,-22.916851],[-43.902646,-22.912075],[-43.901787,-22.912602]]],[[[-43.996893,-22.855942],[-43.995978,-22.85466],[-43.992074,-22.855258],[-43.99491,-22.863682],[-43.998584,-22.863003],[-43.997975,-22.861986],[-43.998069,-22.858882],[-43.997093,-22.857323],[-43.996893,-22.855942]]]]}$q$), 4326), $q${"regra_id":"mangaratiba_lei999_janelas_6_30m","municipio":"Mangaratiba","ibge":"3302601","uf":"RJ","tipo":"zona","regime":"Comprimento > 6,30 m fora de 7h–9h e 18h–20h","nome":"Área urbana de Mangaratiba (aproximada: setores censitários urbanos do IBGE 2022, sem a BR-101 inteira e as RJ)","status":"ativa","confianca":"media","janelas":[{"days":[1,2,3,4,5,6,7],"from":"00:00","to":"07:00"},{"days":[1,2,3,4,5,6,7],"from":"09:00","to":"18:00"},{"days":[1,2,3,4,5,6,7],"from":"20:00","to":"24:00"}],"feriados":"aplica","alvo":{"caminhao":true,"qualquer":[{"campo":"comprimento_m","acima":6.3}]},"autorizacao":"Autorização Especial de Circulação e Estacionamento (arts. 6º e 7º), pedida com 3 dias de antecedência; vale só dentro do horário do art. 3º","excecoes":["Art. 4º: socorro, polícia, fiscalização de trânsito, ambulâncias e utilidade pública (CTB art. 29, VII e VIII)","Art. 5º, I: veículos urbanos de carga com comprimento máximo de 6,30 m e largura máxima de 2,20 m","Art. 5º, II: veículos de autoescola","Art. 6º: concretagem, mudanças, perecíveis e imprensa com Autorização Especial (dentro do horário do art. 3º)"],"vuc":{"comprimento_max_m":6.3,"largura_max_m":2.2,"exige_cadastro":false,"artigo":"Lei 999/2016, art. 5º, I (veículo urbano de carga com até 6,30 m de comprimento e 2,20 m de largura, isento)"},"base_legal":[{"ato":"Lei municipal 999, de 07/04/2016","artigo":"art. 3º (janelas), art. 5º (VUC), arts. 4º, 6º e 7º (exceções)","url":"http://sapl.mangaratiba.rj.leg.br/media/sapl/public/normajuridica/2016/362/362_texto_integral.pdf"}],"nota":"Art. 3º: 'Estará permitida a circulação de qualquer veículo de carga com comprimento entre 6,30 metros a 12,00 metros, na área urbana do município nos seguintes horários: das 7:00 às 9:00 horas e das 18:00 às 20:00 horas'. O ato não fixa dias, então vale todos os dias. Para veículos acima de 12 m vale a restrição do art. 2º (regra separada, desativada), e por isso o alvo usa comprimento acima de 6,30 m como limite inferior. 'Área urbana' não é delimitada no ato: a geometria é o perímetro urbano, aproximado. Art. 15: prazo de adaptação de 180 dias a partir da publicação. A data de publicação não consta no SAPL. Nenhuma alteração ou revogação foi achada no SAPL (ementas '999', 'carga', 'circulação'). GEOMETRIA: 'área urbana' aproximada pelos setores censitários de situação urbana do IBGE (Censo 2022, CD_SIT 1 a 3), que seguem o perímetro urbano legal, MENOS a travessia da BR-101 (Rio-Santos) e das RJ (vias federais/estaduais, fora da competência municipal), com folga de 65 m de cada lado (a API ainda recua a zona 15 m): todas as pistas, alças e ligações da BR-101, com ou sem ref no OSM, e as vias trunk/primary sem ref da travessia (Estrada São João Marcos, Rua Arthur Pires e acessos). A primeira versão (faixa de 30 m só nos ways com ref) deixava trechos da travessia sem ref dentro da zona e bloqueava a Rio-Santos (NO_ROUTE para a carreta, ex.: Itaguaí–Mangaratiba pelo pórtico free flow); decisão de 12/10/2026, mesmo critério de Arcos e Santa Branca: a travessia fica livre. Geometria simplificada a 690 vértices (era 3.137) para caber no limite de 20.000 vértices do exclude_polygons do Valhalla; aproximado. Com o art. 2º (acima de 12 m) desativado, um veículo acima de 12 m também só é barrado fora das janelas.","vigencia_inicio":"2016-04-07","fonte_geometria":"IBGE, setores censitários urbanos do Censo 2022 (RJ_setores_CD2022.gpkg) de Mangaratiba, menos os corredores das rodovias BR-101/RJ do OSM (ODbL); aproximado.","vuc_nota":"A Lei 999/2016 (art. 5º, I) isenta o VUC de até 6,30 m x 2,20 m só na regra das janelas.","fonte":"IBGE, setores censitários do Censo 2022 (situação urbana) menos a travessia da BR-101 e das RJ (folga de 65 m) do OSM (ODbL), PBF local","aproximado":true,"verificado_em":"2026-10-11"}$q$::jsonb, $q$2016-04-07$q$::timestamptz, null::timestamptz),
